export default async function scan({ sourceId, collectionId, previous }, ctx) {
  const s = previous ?? {
    phase: "notion",
    cursor: null,
    seen: [],
    pages: [],
    items: [],
    offset: 0,
  };
  if (!sourceId || !collectionId)
    throw Error("Configure Notion data source and Webflow collection");
  if (s.phase === "done") return { state: s, more: false };
  if (s.phase === "notion") {
    const r = await ctx.actions.call("notion.query_data_source", {
      dataSourceId: sourceId,
      pageSize: 100,
      ...(s.cursor ? { startCursor: s.cursor } : {}),
    });
    if (!Array.isArray(r?.results) || typeof r.has_more !== "boolean")
      throw Error("Invalid Notion page");
    if (r.has_more && (!r.next_cursor || s.seen.includes(r.next_cursor)))
      throw Error("Invalid Notion cursor");
    const ids = new Set(s.pages.map((p) => p.id));
    for (const p of r.results) {
      if (!p.id || ids.has(p.id)) throw Error("Invalid or duplicate Notion page");
      ids.add(p.id);
    }
    return {
      state: {
        ...s,
        pages: [...s.pages, ...r.results],
        phase: r.has_more ? "notion" : "webflow",
        cursor: r.has_more ? r.next_cursor : null,
        seen: r.has_more ? [...s.seen, r.next_cursor] : [],
      },
      more: true,
    };
  }
  if (s.phase !== "webflow") throw Error("Invalid scan phase");
  const r = await ctx.actions.call("webflow.list_collection_items", {
    collectionId,
    limit: 100,
    offset: s.offset,
  });
  if (!Array.isArray(r?.items) || r.items.length > 100) throw Error("Invalid Webflow page");
  const ids = new Set(s.items.map((p) => p.id));
  for (const p of r.items) {
    if (!p.id || ids.has(p.id)) throw Error("Invalid or duplicate Webflow item");
    ids.add(p.id);
  }
  const offset = s.offset + r.items.length;
  const more = r.items.length === 100;
  return {
    state: { ...s, items: [...s.items, ...r.items], offset, phase: more ? "webflow" : "done" },
    more,
  };
}

