export default async function next({ scan, previous }, ctx) {
  const s = previous ?? { index: 0, phase: "page", cursor: null, seen: [], blocks: [] };
  if (s.index >= scan.pages.length)
    return { state: s, more: false, ready: false, page: {}, blocks: [] };
  const p = scan.pages[s.index];
  if (!p?.id || !p.properties) throw Error("Invalid Notion page");
  const enabled = p.properties["Sync to Webflow?"];
  if (enabled?.type !== "checkbox") throw Error("Configure Sync to Webflow? checkbox");
  if (!enabled.checkbox)
    return { state: { ...s, index: s.index + 1 }, more: true, ready: false, page: {}, blocks: [] };
  const slug = p.properties.slug;
  if (slug?.type !== "rich_text" || !Array.isArray(slug.rich_text))
    throw Error("Configure slug rich text");
  const slugValue = slug.rich_text.map((x) => x.plain_text ?? x.text?.content ?? "").join("");
  const titles = Object.values(p.properties).filter((x) => x.type === "title");
  if (titles.length !== 1 || !Array.isArray(titles[0].title))
    throw Error("Expected one title property");
  const name = titles[0].title.map((x) => x.plain_text ?? x.text?.content ?? "").join("");
  if (!name) throw Error("Missing post title");
  const wanted =
    slugValue ||
    name
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
  if (!wanted) throw Error("Cannot create slug");
  const slugFor = (x) => {
    const t = x.properties?.slug?.rich_text ?? [];
    const v = t.map((y) => y.plain_text ?? y.text?.content ?? "").join("");
    const title = Object.values(x.properties ?? {}).find((y) => y.type === "title")?.title ?? [];
    return (
      v ||
      title
        .map((y) => y.plain_text ?? y.text?.content ?? "")
        .join("")
        .toLowerCase()
        .normalize("NFKD")
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "")
    );
  };
  if (
    scan.pages.some(
      (x) =>
        x.id !== p.id &&
        x.properties?.["Sync to Webflow?"]?.checkbox === true &&
        slugFor(x) === wanted,
    )
  )
    throw Error("Duplicate selected Notion slug");
  const matches = scan.items.filter((x) => x.fieldData?.slug === wanted);
  if (matches.length > 1) throw Error("Ambiguous Webflow slug");
  const r = await ctx.actions.call("notion.list_block_children", {
    blockId: p.id,
    pageSize: 100,
    ...(s.cursor ? { startCursor: s.cursor } : {}),
  });
  if (!Array.isArray(r?.results) || typeof r.has_more !== "boolean")
    throw Error("Invalid Notion block page");
  if (r.has_more && (!r.next_cursor || s.seen.includes(r.next_cursor)))
    throw Error("Invalid block cursor");
  const blocks = [...s.blocks, ...r.results];
  if (r.has_more)
    return {
      state: { ...s, cursor: r.next_cursor, seen: [...s.seen, r.next_cursor], blocks },
      more: true,
      ready: false,
      page: {},
      blocks: [],
    };
  const cover = p.cover?.external?.url;
  if (!cover) throw Error("Post must have an external cover image");
  return {
    state: { index: s.index + 1, phase: "page", cursor: null, seen: [], blocks: [] },
    more: true,
    ready: true,
    page: { id: p.id, name, slug: wanted, cover, itemId: matches[0]?.id ?? null },
    blocks,
  };
}

