const escape = (value) =>
  String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
function rich(items) {
  if (!Array.isArray(items)) throw Error("Missing block rich text");
  return items
    .map((item) => {
      let text = escape(item.plain_text ?? item.text?.content ?? "");
      const a = item.annotations ?? {};
      if (a.bold) text = `<strong>${text}</strong>`;
      if (a.italic) text = `<em>${text}</em>`;
      const link = item.href ?? item.text?.link?.url;
      if (link) {
        const url = new URL(link);
        if (!["https:", "http:"].includes(url.protocol)) throw Error("Unsupported link URL");
        text = `<a href="${escape(url.href)}">${text}</a>`;
      }
      return text;
    })
    .join("");
}
export default function render({ blocks }) {
  if (!Array.isArray(blocks)) throw Error("Invalid blocks");
  let html = "",
    list = null;
  const close = () => {
    if (list) html += `</${list}>`;
    list = null;
  };
  for (const block of blocks) {
    const t = block.type,
      data = block[t];
    if (!data || block.has_children) throw Error("Unsupported or nested Notion block");
    if (t === "bulleted_list_item" || t === "numbered_list_item") {
      const tag = t === "bulleted_list_item" ? "ul" : "ol";
      if (tag !== list) {
        close();
        list = tag;
        html += `<${tag}>`;
      }
      html += `<li>${rich(data.rich_text ?? data.text)}</li>`;
      continue;
    }
    close();
    if (["paragraph", "heading_1", "heading_2", "heading_3", "quote", "code"].includes(t)) {
      const tag = {
        paragraph: "p",
        heading_1: "h1",
        heading_2: "h2",
        heading_3: "h3",
        quote: "blockquote",
        code: "pre",
      }[t];
      const content = rich(data.rich_text ?? data.text);
      html +=
        t === "code"
          ? `<pre><code>${content}</code></pre>`
          : `<${tag}>${content || (t === "paragraph" ? " " : "")}</${tag}>`;
    } else if (t === "image") {
      const url = new URL(data.file?.url ?? data.external?.url);
      if (url.protocol !== "https:") throw Error("Image URL must use HTTPS");
      const caption = rich(data.caption ?? []);
      html += `<figure><img src="${escape(url.href)}" alt="${escape((data.caption ?? []).map((x) => x.plain_text ?? x.text?.content ?? "").join(""))}"><figcaption>${caption}</figcaption></figure>`;
    } else throw Error("Unsupported Notion block: " + t);
  }
  close();
  return { html };
}

