import { createHash } from "node:crypto";
export default async function plan(
  { page, html, acknowledge, resolution, confirmedItemId, previous },
  ctx,
) {
  const fieldData = {
    name: page.name,
    slug: page.slug,
    "blog-post-richt-text": html,
    "blog-post-featured-image-photo": { url: page.cover },
    "blog-post-thumbnail-image-photo": { url: page.cover },
  };
  const hash = createHash("sha256").update(JSON.stringify(fieldData)).digest("hex"),
    key = "notion-webflow:" + page.id;
  let state = (await ctx.state.get(key)) ?? { phase: "webflow", itemId: page.itemId };
  let resolved = false;
  if (state.pending) {
    if (state.hash !== hash) throw Error("Content changed while pending " + key);
    if (acknowledge !== key + ":" + state.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending write " + key + ":" + state.pending);
    if (resolution === "confirmed") {
      resolved = true;
      if (state.pending === "webflow") {
        if (!confirmedItemId) throw Error("Enter confirmed Webflow item ID");
        state.itemId = confirmedItemId;
        state.phase = "notion";
      } else if (state.pending === "notion") state.phase = "slack";
      else state.phase = "done";
    }
    state.pending = null;
    await ctx.state.set(key, state);
  }
  const fresh = !previous || previous.pageId !== page.id || previous.action === "done";
  if (fresh && state.phase === "done" && !resolved && !resolution)
    state = { phase: "webflow", itemId: page.itemId };
  state.hash = hash;
  let action = state.phase;
  if (action === "webflow") action = state.itemId ? "update" : "create";
  if (action !== "done") {
    state.pending = state.phase;
    await ctx.state.set(key, state);
  }
  return {
    pageId: page.id,
    action,
    previous: { action, pageId: page.id },
    key,
    fieldData,
    itemId: state.itemId || "unused",
    properties: { slug: { rich_text: [{ text: { content: page.slug } }] } },
    text: "[Notion to Webflow] " + page.name + " successfully synced",
  };
}

