export default async function confirm({ key, phase, result, page, channelId }, ctx) {
  const s = await ctx.state.get(key);
  if (!s || s.pending !== phase) throw Error("Missing pending " + phase);
  if (phase === "webflow") {
    if (
      !result?.id ||
      result.fieldData?.slug !== page.slug ||
      result.isDraft !== true ||
      (s.itemId && s.itemId !== result.id)
    )
      throw Error("Webflow write not confirmed");
    s.itemId = result.id;
    s.phase = "notion";
  } else if (phase === "notion") {
    if (result?.id !== page.id) throw Error("Notion write not confirmed");
    s.phase = "slack";
  } else {
    if (!result?.ts || result.channelId !== channelId) throw Error("Slack write not confirmed");
    s.phase = "done";
  }
  s.pending = null;
  await ctx.state.set(key, s);
  return { ok: true };
}

